func (v SpecValue) Equal(o attr.Value) bool {
	other, ok := o.(SpecValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.AddressFamilies.Equal(other.AddressFamilies) {
		return false
	}

	if !v.AreaIds.Equal(other.AreaIds) {
		return false
	}

	if !v.Enabled.Equal(other.Enabled) {
		return false
	}

	if !v.HelloPadding.Equal(other.HelloPadding) {
		return false
	}

	if !v.Level1.Equal(other.Level1) {
		return false
	}

	if !v.Level2.Equal(other.Level2) {
		return false
	}

	if !v.LevelCapability.Equal(other.LevelCapability) {
		return false
	}

	if !v.Lfa.Equal(other.Lfa) {
		return false
	}

	if !v.LspMtu.Equal(other.LspMtu) {
		return false
	}

	if !v.MaxEcmp.Equal(other.MaxEcmp) {
		return false
	}

	if !v.Overload.Equal(other.Overload) {
		return false
	}

	if !v.PassiveOnly.Equal(other.PassiveOnly) {
		return false
	}

	if !v.Redistribution.Equal(other.Redistribution) {
		return false
	}

	if !v.ReferenceBandwidthGbps.Equal(other.ReferenceBandwidthGbps) {
		return false
	}

	if !v.Timers.Equal(other.Timers) {
		return false
	}

	if !v.TlvConfig.Equal(other.TlvConfig) {
		return false
	}

	return true
}

